function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'NeighborSum' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with NeighborSum(grid).';
  const grid = args[0][0];
  if (!Array.isArray(grid) || grid.length < 3 || grid.length > 10) return 'grid needs 3 to 10 rows.';
  const n = grid.length;
  const seen = new Set();
  for (const line of grid) {
    if (!Array.isArray(line) || line.length !== n) return 'grid must be square: n rows of n values.';
    for (const v of line) {
      if (!Number.isInteger(v) || v < 0 || v >= n * n) return 'Grid values are whole numbers from 0 to n^2 - 1.';
      if (seen.has(v)) return 'Grid values must be distinct.';
      seen.add(v);
    }
  }
  if (operations.length - 1 > 2 * n * n) return 'At most 2 * n^2 calls to adjacentSum and diagonalSum.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'adjacentSum' && operations[i] !== 'diagonalSum') return 'Only adjacentSum and diagonalSum can follow the constructor.';
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 0 || a[0] >= n * n) return 'Each call takes one value from 0 to n^2 - 1.';
  }
  return null;
}

