class NeighborSum {
  constructor(grid) {
    this.grid = grid;
    this.n = grid.length;
    this.position = new Map();
    for (let row = 0; row < this.n; row++) {
      for (let col = 0; col < this.n; col++) {
        this.position.set(grid[row][col], [row, col]);
      }
    }
  }

  adjacentSum(value) {
    return this.sumAround(value, [[-1, 0], [1, 0], [0, -1], [0, 1]]);
  }

  diagonalSum(value) {
    return this.sumAround(value, [[-1, -1], [-1, 1], [1, -1], [1, 1]]);
  }

  sumAround(value, offsets) {
    const [row, col] = this.position.get(value);
    let sum = 0;
    for (const [dr, dc] of offsets) {
      const r = row + dr;
      const c = col + dc;
      if (r >= 0 && r < this.n && c >= 0 && c < this.n) {
        sum += this.grid[r][c];
      }
    }
    return sum;
  }
}

