class NeighborSum {
  // No index: every call searches the whole grid for the value, then adds up every cell at the right distance.
  constructor(grid) {
    this.cells = grid.map(line => line.slice());
  }
  total(value, keep) {
    let home = null;
    this.cells.forEach((line, r) => line.forEach((v, c) => { if (v === value) home = [r, c]; }));
    let total = 0;
    this.cells.forEach((line, r) => line.forEach((v, c) => {
      if (keep(Math.abs(r - home[0]), Math.abs(c - home[1]))) total += v;
    }));
    return total;
  }
  adjacentSum(value) {
    return this.total(value, (rows, cols) => rows + cols === 1);
  }
  diagonalSum(value) {
    return this.total(value, (rows, cols) => rows === 1 && cols === 1);
  }
}

