function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.7 ? 10 : int(8, 9)) : int(3, 5);
  const values = Array.from({ length: n * n }, (_, i) => i);
  const style = int(0, 3);
  if (style === 1) values.reverse();
  if (style >= 2) {
    for (let i = values.length - 1; i > 0; i--) {
      const j = int(0, i);
      [values[i], values[j]] = [values[j], values[i]];
    }
  }
  const grid = Array.from({ length: n }, (_, row) => values.slice(row * n, row * n + n));
  const calls = large ? 2 * n * n : int(1, 10);
  const operations = ['NeighborSum'];
  const args = [[grid]];
  for (let i = 0; i < calls; i++) {
    operations.push(rand() < 0.5 ? 'adjacentSum' : 'diagonalSum');
    // Border cells, and corners above all, have missing neighbours, so ask about them often.
    const pick = rand();
    const row = pick < 0.3 ? (rand() < 0.5 ? 0 : n - 1) : int(0, n - 1);
    const col = pick < 0.3 || pick > 0.8 ? (rand() < 0.5 ? 0 : n - 1) : int(0, n - 1);
    args.push([grid[row][col]]);
  }
  return [operations, args];
}
